test('createInvoice normalizes mixed case with spaces', () => {
  const result = createInvoice({
    customerId: '  C-003  ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice applies tier discount based on normalized customer ID', () => {
  const goldResult = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(goldResult.ok, true);
  assert.equal(goldResult.value.lines[0].discountPercent, 5);

  const silverResult = createInvoice({
    customerId: '  C-003  ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(silverResult.ok, true);
  assert.equal(silverResult.value.lines[0].discountPercent, 2.5);
});

